style.css:
@-moz-document domain("google.com") {
/* Fondo principal de Google */
    body, #viewport, .MainPage, #cnt, .rsb, .fbar {
        background-color: #000000 !important;
        color: #ffffff !important;
    }
    /* Barra de búsqueda */
    .gLFyf, .RNNXgb {
        background-color: #111111 !important;
        border: 1px solid #333333 !important;
        color: #ffffff !important;
    }
    /* Tarjetas de resultados y enlaces */
    .g, .KP7wve, .tF2Cxc {
        background-color: #000000 !important;
    }
    a {
        color: #8ab4f8 !important;
    }
    a:visited {
        color: #c58af9 !important;
    }
    span, em {
        color: #e8eaed !important;
    }
}

@-moz-document domain("youtube.com") {
/* Fondo general de YouTube */
    ytd-app, 
    ytd-watch-flexy, 
    #page-manager, 
    #columns, 
    #content-container,
    #masthead-container {
        background: #000000 !important;
        background-color: #000000 !important;
    }
    /* Barra de navegación superior */
    #masthead, #background.ytd-masthead {
        background-color: #000000 !important;
    }
    /* Barra de búsqueda de YouTube */
    #container.ytd-searchbox, #search-icon-legacy.ytd-searchbox {
        background-color: #121212 !important;
        border: 1px solid #222222 !important;
    }
    /* Texto principal */
    yt-formatted-string, span, #video-title {
        color: #ffffff !important;
    }
    /* Panel lateral */
    ytd-guide-renderer, #sections.ytd-guide-renderer {
        background-color: #000000 !important;
    }
}
